const engine = "omnivoice";
const voice = "Arek";
const items = $input.all();

if (items.length !== 1 || !items[0].binary?.audio) {
  throw new Error(engine + ': missing binary.audio');
}

const buf = await this.helpers.getBinaryDataBuffer(0, 'audio');

if (
  buf.length < 44 ||
  buf.toString('ascii', 0, 4) !== 'RIFF' ||
  buf.toString('ascii', 8, 12) !== 'WAVE'
) {
  throw new Error(engine + ': invalid WAV header');
}

let offset = 12;
let channels = null;
let sampleRate = null;
let bits = null;
let format = null;
let dataBytes = 0;

while (offset + 8 <= buf.length) {
  const type = buf.toString('ascii', offset, offset + 4);
  const length = buf.readUInt32LE(offset + 4);

  if (length > buf.length - offset - 8) {
    throw new Error(engine + ': truncated WAV chunk');
  }

  if (type === 'fmt ') {
    if (length < 16) {
      throw new Error(engine + ': invalid fmt chunk');
    }
    format = buf.readUInt16LE(offset + 8);
    channels = buf.readUInt16LE(offset + 10);
    sampleRate = buf.readUInt32LE(offset + 12);
    bits = buf.readUInt16LE(offset + 22);
  }

  if (type === 'data') {
    dataBytes += length;
  }

  offset += 8 + length + (length % 2);
}

if (
  format !== 1 ||
  channels !== 1 ||
  bits !== 16 ||
  !sampleRate ||
  dataBytes < 1000
) {
  throw new Error(engine + ': expected mono PCM16 WAV');
}

const duration =
  dataBytes / (sampleRate * channels * bits / 8);

if (duration < 0.3 || duration > 120) {
  throw new Error(engine + ': invalid WAV duration');
}

return [{
  json: {
    engine,
    voice,
    status: 'verified_wav',
    real_tts: true,
    wav_bytes: buf.length,
    data_bytes: dataBytes,
    sample_rate: sampleRate,
    audio_duration_sec: Number(duration.toFixed(4))
  },
  binary: items[0].binary
}];

